def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_d = me.count('D')

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    opp_d_streak = streak(opp, 'D')
    last_op = opp[-1]
    last_me = me[-1]
    remaining = 100 - n

    if remaining <= 0:
        return 'D'

    if last_op == 'D':
        if opp_d_streak >= 3:
            return 'D'
        if n >= 6:
            r14 = opp[-5:-1]
            rd = r14.count('D')
            if rd == 0 and rng.random() < 0.18:
                return 'C'
        if last_me == 'D':
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if remaining <= 3:
            return 'D'
        return 'D' if rng.random() < 0.92 else 'C'

    if remaining == 1:
        return 'D'
    if remaining == 2:
        if opp_d_streak == 0 and opp_d == 0:
            return 'D'
        return 'C'

    early_coop = True
    if opp_d >= 3 and opp_d * 2 >= n:
        early_coop = False

    if early_coop and n < 20:
        return 'C'

    if opp_d_streak == 0:
        if n >= 12:
            r10 = opp[-10:]
            rd = r10.count('D')
            if rd >= 2:
                if rng.random() < 0.4:
                    return 'D'
        if n >= 25:
            coop_rate = opp_c / float(n)
            if coop_rate >= 0.9:
                if n % 13 == 0:
                    return 'D'
                return 'C'
            if coop_rate >= 0.7:
                if rng.random() < 0.06:
                    return 'D'
                return 'C'
            if coop_rate >= 0.45:
                if n % 5 == 0:
                    return 'D'
                return 'C'
        return 'C'

    if last_op == 'C':
        if opp_d_streak == 0 and my_d < opp_d + 2:
            return 'C'
        if opp_d * 3 >= n * 2:
            return 'D' if rng.random() < 0.85 else 'C'
        if opp_d * 3 > n:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'C'

    return 'C'
